   993                  if (b1 < a0) {
   994                      jbig2_error(ctx, JBIG2_SEVERITY_WARNING, -1, "ignoring negative VR(3) run");
   995                      b1 = a0;
   996                  }
   997                  if (a0 < mmr->width)
   998                      jbig2_set_bits(dst, a0, b1);
   999              }
  1000              a0 = b1;
  1001              c = !c;
  1002          }
  1003
  1004          else if ((word >> (32 - 3)) == 2) {
  1005              /* printf ("VL(1)\n"); */
